UPDATE companies SET description='Founded in 1961, Northern Illinois Steel Supply Co. has been based in Channahon, Illinois for over six decades. The company operates an 80,000-square-foot facility that combines warehousing and fabrication under one roof, and it supports regional customers through additional offices in Chicago and Houston, Texas.

The company’s product line focuses on domestic steel, offering aluminum, stainless steel, plates, sheets, structural shapes, bars, tubing, and grating. It complements its inventory with custom precision fabrication services, allowing customers to source both raw material and finished components from a single supplier.

Northern Illinois Steel Supply serves a customer base concentrated in Illinois and Indiana, with its Channahon headquarters acting as the primary distribution and fabrication hub. The Chicago and Texas offices extend its sales reach, though the company does not disclose specific industry sectors or major accounts.

The company attributes its longevity to responsive service and a highly skilled workforce, stating that its strength lies in delivering high-quality products and responsive service. It also cites its state-of-the-art equipment and fully stocked domestic steel inventory as factors that set it apart.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom precision fabrication", "Steel product distribution", "Warehousing and inventory management"], "industries": [], "materials": ["Aluminum", "Stainless Steel", "Steel Plates", "Sheets", "Structural", "Bars", "Tubing", "Grating"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["80,000-square-foot warehouse and fabrication facility", "Domestic steel product inventory", "Custom precision fabrication", "Responsive service and skilled workforce", "State-of-the-art equipment"], "facts_used": ["Founded 1961 -> db", "Headquarters Channahon, Illinois -> db", "80,000 sq ft warehouse and fabrication facility -> /", "Domestic steel products: aluminum, stainless steel, plates, sheets, structural, bars, tubing, grating -> /", "Custom precision fabrication -> /", "Sales offices in Chicago and Houston, Texas -> /", "Serves customers in Illinois and Indiana -> /", "Strength in high-quality products and responsive service -> /", "Skilled workforce and state-of-the-art equipment -> /"], "company_type": "Distributor / reseller", "makes_products": "yes", "type_evidence": "Our 80,000 square foot warehouse and fabrication facilities are fully stocked to efficiently supply our customers with premium quality domestic steel products and custom, precision fabrication at competitive prices.", "founded_year": "1961", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='northern-illinois-steel-supply' AND approved AND profile IS NULL;
UPDATE companies SET description='Northern Wire operates from a 100,000-square-foot facility in Merrill, Wisconsin. Established in 1970, the company has grown into one of the country''s largest custom wire-forming operations and now operates as part of the MW Components family, the largest single-source supplier of specialty fasteners in the nation.

The company manufactures complex wire forms, specialty bends, and welded products with wire processing capabilities extending up to 12 feet. Its shop runs 25 presses ranging from 10 to 600 tons for flattening, punching, and staking, plus resistance and wire-feed welding. Northern Wire combines automated CNC wire bending with manual forming to handle geometries that automation alone cannot achieve, and it performs a full suite of secondary operations in house — including chamfering, coining, drilling, extruding, grooving, knurling, machining, piercing, tapping, and threading — alongside standalone zinc plating and powder coating services.

Northern Wire serves original equipment manufacturers and blue-chip wholesalers and distributors across aerospace, agriculture, appliances, construction, consumer goods, energy, industrial, lawn and garden, medical, power equipment, and recreation markets. Its blended sourcing model pairs domestic quality control with licensed product manufacturing and design consultation to mitigate supply-chain disruptions.

The company emphasizes engineering excellence and quality at all levels, holding ISO 9001:2015 certification and QSLM Class 2 compliance with tools calibrated and traceable to NIST. In-house secondary services and a barcode-driven distribution system are cited as key factors in reducing lead times for time-sensitive deliveries.', certifications=ARRAY['ISO 9001:2015','QSLM Class 2','Tools Calibrated & Traceable to NIST']::text[], profile='{"capabilities": ["Automated CNC wire bending", "Manual wire forming", "Wire forming up to 12 feet", "Resistance welding", "Wire feed welding", "Press operations (10-600 tons)", "Flattening", "Punching", "Staking", "Threading", "Piercing", "Zinc plating", "Powder coating", "Chamfering", "Coining", "Collaring", "Drilling", "Extruding", "Grooving", "Knurling", "Machining", "Tapping", "Blended sourcing", "Barcode distribution services"], "industries": ["Aerospace", "Agriculture", "Appliances", "Construction", "Consumer Goods", "Energy", "Industrial", "Lawn & Garden", "Medical", "Power Equipment", "Recreation"], "materials": [], "equipment": ["25 presses (10-600 tons)", "Automated CNC machines"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["In-house secondary operations (chamfering, coining, drilling, extruding, grooving, knurling, machining, piercing, tapping, threading, welding) reducing lead times", "Blended fastener sourcing with domestic quality control for high-volume specialty wire forms", "Combined automated CNC and manual wire bending for complex geometries", "Standalone zinc plating and powder coating services", "Barcode-driven distribution with custom labeling and packaging"], "facts_used": ["Headquarters: Merrill, Wisconsin -> db", "Founded: 1970 -> /about", "Facility size: 100,000 sq ft -> /about", "Part of MW Components family -> /about", "Wire processing up to 12 feet -> /, /about", "25 presses, 10-600 tons -> /", "Resistance and wire feed welding -> /", "Automated CNC and manual wire bending -> /about",